import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.B7PviQjB.js";const u=JSON.parse('{"title":"Claude Code plugin","description":"Install the Wafflebase plugin for Claude Code so Claude can find, read, and edit your documents, with your confirmation before every change.","frontmatter":{"title":"Claude Code plugin","description":"Install the Wafflebase plugin for Claude Code so Claude can find, read, and edit your documents, with your confirmation before every change.","type":"how-to"},"headers":[],"relativePath":"developers/claude-code-plugin.md","filePath":"developers/claude-code-plugin.md"}'),d={name:"developers/claude-code-plugin.md"};function l(n,e,i,r,c,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="claude-code-plugin" tabindex="-1">Claude Code plugin <a class="header-anchor" href="#claude-code-plugin" aria-label="Permalink to &quot;Claude Code plugin&quot;">​</a></h1><p>Install the Wafflebase plugin so Claude Code can find, read, create, and edit your sheets, docs, decks, notes, boards, and files.</p><p>Claude works through the <a href="/docs/developers/cli/"><code>wafflebase</code> CLI</a> on your computer, signed in as you. The plugin teaches Claude the commands and asks you before anything changes.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>Claude Code installed.</li><li>Node.js 20.18.1 or later, for the CLI.</li><li>A Wafflebase account, or the API URL of your own server.</li></ul></div><h2 id="install-the-plugin" tabindex="-1">Install the plugin <a class="header-anchor" href="#install-the-plugin" aria-label="Permalink to &quot;Install the plugin&quot;">​</a></h2><ol><li><p>In a terminal, install the CLI and sign in:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @wafflebase/cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>For your own server, run <code>wafflebase login --server https://api.example.com</code>.</p></li><li><p>In Claude Code, add the Wafflebase marketplace:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin marketplace add wafflebase/wafflebase</span></span></code></pre></div></li><li><p>Install the plugin:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin install wafflebase@wafflebase</span></span></code></pre></div></li><li><p>Check the setup:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/wafflebase:setup</span></span></code></pre></div></li></ol><p>Claude checks the CLI version, your sign-in, and your workspace, then reports how many documents it can see. If a step needs you, such as signing in, it stops and says what to run.</p><h2 id="find-a-document" tabindex="-1">Find a document <a class="header-anchor" href="#find-a-document" aria-label="Permalink to &quot;Find a document&quot;">​</a></h2><ol><li><p>Run <code>/wafflebase:find</code> with a few words from the title:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/wafflebase:find meeting notes</span></span></code></pre></div></li></ol><p>Claude replies with a table of matching documents (title, type, last updated, and a link), newest first, up to 15 rows. If nothing matches, it shows the five most recently updated documents. It doesn&#39;t open a document&#39;s content unless you ask about it.</p><h2 id="publish-a-local-file" tabindex="-1">Publish a local file <a class="header-anchor" href="#publish-a-local-file" aria-label="Permalink to &quot;Publish a local file&quot;">​</a></h2><ol><li><p>Run <code>/wafflebase:publish</code> with a file path and, optionally, a title:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/wafflebase:publish docs/release-notes.md &quot;Release notes&quot;</span></span></code></pre></div></li><li><p>Claude states the plan in one line. Approve the command when Claude Code asks.</p></li></ol><p>Claude replies with a link to the new document. The file type decides what it becomes:</p><table tabindex="0"><thead><tr><th>File</th><th>Becomes</th></tr></thead><tbody><tr><td><code>.md</code>, <code>.markdown</code></td><td>A note</td></tr><tr><td><code>.csv</code></td><td>A sheet</td></tr><tr><td><code>.docx</code></td><td>A doc</td></tr><tr><td><code>.pptx</code></td><td>A deck</td></tr><tr><td>Anything else</td><td>A stored file</td></tr></tbody></table><p>Publishing always creates a new document. To update an existing one, ask Claude to replace it by name.</p><h2 id="ask-claude-to-work-on-your-documents" tabindex="-1">Ask Claude to work on your documents <a class="header-anchor" href="#ask-claude-to-work-on-your-documents" aria-label="Permalink to &quot;Ask Claude to work on your documents&quot;">​</a></h2><p>Ask in plain language. For example:</p><ul><li>&quot;Find last week&#39;s meeting notes and summarize the decisions.&quot;</li><li>&quot;What does the Q3 revenue sheet say about churn by region?&quot;</li><li>&quot;Turn <code>bench/results.csv</code> into a sheet and add a total row.&quot;</li><li>&quot;Add a slide after slide 3 of the roadmap deck using the title layout.&quot;</li><li>&quot;Move every doc with &#39;draft&#39; in the title into the Drafts folder.&quot;</li><li>&quot;List the open comments on the launch plan and resolve the ones about typos.&quot;</li></ul><p>Claude links every document it mentions or changes. Before it replaces a whole document, it makes a copy as a restore point, because a replace can&#39;t be undone.</p><h2 id="know-what-asks-for-confirmation" tabindex="-1">Know what asks for confirmation <a class="header-anchor" href="#know-what-asks-for-confirmation" aria-label="Permalink to &quot;Know what asks for confirmation&quot;">​</a></h2><p>A plugin hook checks every <code>wafflebase</code> command Claude runs. By default it asks you before any change:</p><table tabindex="0"><thead><tr><th>Command</th><th>What happens</th></tr></thead><tbody><tr><td>A single read-only command, such as <code>list</code>, <code>get</code>, or <code>content</code></td><td>Your own Claude Code permission rules decide. By default, Claude Code asks.</td></tr><tr><td>Writes: create, rename, set cells, import, add slides</td><td>Asks</td></tr><tr><td>Deletes, whole-document replaces, <code>--replace</code> imports</td><td>Always asks</td></tr><tr><td>Exports and downloads that write a local file, and uploads of a local file</td><td>Always asks</td></tr><tr><td><code>login</code>, <code>logout</code>, <code>ctx switch</code>, <code>api-keys create</code>, <code>templates publish</code>, <code>templates use</code>, <code>bots create</code>, <code>bots pair-code</code>, <code>agent pair</code></td><td>Always asks</td></tr><tr><td>Any command with <code>--server</code>, <code>--api-key</code>, <code>--profile</code>, or <code>--frontend</code>, or with a <code>VAR=</code> prefix</td><td>Always asks</td></tr><tr><td>A cell batch that deletes cells or reads its data from standard input</td><td>Always asks</td></tr><tr><td>A command inside a pipe, <code>&amp;&amp;</code> chain, or substitution, or one the plugin doesn&#39;t recognize</td><td>Asks</td></tr><tr><td>Any change to the plugin&#39;s own files</td><td>Always asks</td></tr></tbody></table><p>The skills also tell Claude to treat text inside your documents as data: an instruction written in a cell or comment is reported to you, not followed. That is guidance, which is why the confirmations are enforced by the hook.</p><h2 id="turn-on-auto-approval" tabindex="-1">Turn on auto-approval <a class="header-anchor" href="#turn-on-auto-approval" aria-label="Permalink to &quot;Turn on auto-approval&quot;">​</a></h2><p>Two plugin settings skip some prompts. Both are off by default.</p><ol><li>In Claude Code, run <code>/plugin</code>.</li><li>Choose the installed <code>wafflebase</code> plugin and open its options.</li><li>Turn on <strong>Auto-allow read-only commands</strong>, <strong>Auto-approve document writes</strong>, or both.</li></ol><p><strong>Auto-allow read-only commands</strong> runs a single plain read without asking. <strong>Auto-approve document writes</strong> runs document edits without asking. Everything marked &quot;Always asks&quot; above still asks.</p><div class="warning custom-block"><p class="custom-block-title">Auto-approval trusts your shell</p><p>An approved command trusts that <code>wafflebase</code> in Claude Code&#39;s shell is still the real CLI. An earlier command, such as one that changes <code>PATH</code> or adds an alias, could swap it. Your own allow rules, such as <code>Bash(wafflebase docs list:*)</code>, carry the same risk.</p></div><h2 id="point-links-at-your-own-web-app" tabindex="-1">Point links at your own web app <a class="header-anchor" href="#point-links-at-your-own-web-app" aria-label="Permalink to &quot;Point links at your own web app&quot;">​</a></h2><p>Claude builds document links from the server you signed in to: <code>api.example.com</code> links to <code>example.com</code>, and a local <code>localhost:3000</code> server links to <code>localhost:5173</code>. If links don&#39;t open, set the web app&#39;s address before starting Claude Code:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WAFFLEBASE_WEB_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://office.example.com</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><code>WAFFLEBASE_WEB_URL</code></td><td>Web app address for document links. A path is kept, for an app served under one.</td></tr><tr><td><code>WAFFLEBASE_API_KEY</code></td><td>Use a workspace API key instead of <code>wafflebase login</code>. Also set <code>WAFFLEBASE_WORKSPACE</code>; Settings → API keys prints both lines when it creates the key.</td></tr><tr><td><strong>Auto-allow read-only commands</strong></td><td>See <a href="#turn-on-auto-approval">Turn on auto-approval</a>.</td></tr><tr><td><strong>Auto-approve document writes</strong></td><td>See <a href="#turn-on-auto-approval">Turn on auto-approval</a>.</td></tr></tbody></table><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Claude can do only what the CLI can. It can&#39;t create a board or open a comment thread on doc text, for example. See <a href="/docs/developers/cli/automation.html#known-limitations">Automation and agents</a>.</li><li><code>wafflebase status</code> reports what your commands authenticate with in <code>auth</code> (<code>session</code>, <code>api-key</code> or <code>none</code>). <code>/wafflebase:setup</code> reads it, so an API key no longer looks like being signed out.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/developers/bots.html">Put a bot to work</a> to answer chat mentions from this session with <code>/wafflebase:listen</code>.</li><li><a href="/docs/developers/cli/">Install and sign in</a> for CLI sign-in, profiles, and API keys.</li><li><a href="/docs/developers/cli/automation.html">Automation and agents</a> for safety levels, skills, and error codes.</li><li><a href="/docs/developers/cli/documents.html">Documents and notes</a> for the commands Claude runs most.</li><li><a href="/docs/developers/cli/slides-and-board.html#check-a-deck-before-you-share-it">Slides and boards</a> for how Claude checks a deck it builds.</li></ul>`,36)])])}const m=t(d,[["render",l]]);export{u as __pageData,m as default};
